"""Build the offline review gallery from the native capture manifests."""
import json
from pathlib import Path
root = Path(__file__).resolve().parents[1] / 'build/equipment-review'
entries = json.loads((root/'manifest.json').read_text()) + json.loads((root/'held-manifest.json').read_text())
assert len({e['id'] for e in entries}) == len(entries)
assert all((root/e['file']).is_file() for e in entries)
page = '''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Frostmere · Equipment review</title>
<style>
*{box-sizing:border-box}body{margin:0;background:#101820;color:#e4ebed;font:16px system-ui}header{padding:48px 5vw 25px;background:linear-gradient(120deg,#263841,#101820)}small{color:#ddba79;letter-spacing:3px}h1{font:44px Georgia;margin:15px 0}p{max-width:850px;color:#b8c9d0;line-height:1.6}nav{position:sticky;top:0;background:#101820f5;padding:18px 5vw;z-index:1;display:flex;flex-wrap:wrap;gap:9px;border-bottom:1px solid #34424b}button,input,select{font:inherit;border:1px solid #52646d;border-radius:6px;background:#20313c;color:#e5ecef;padding:10px;cursor:pointer}input{min-width:260px}main{padding:20px 5vw 60px}#count{color:#c7ae7d;margin:10px 0 20px}#grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(320px,1fr));gap:20px}article{background:#1c2933;border:1px solid #34424b;border-radius:9px;overflow:hidden}article button{padding:0;border:0;width:100%;display:block}article img{width:100%;aspect-ratio:1.6;display:block}article div{padding:17px}h2{font-size:17px;margin:7px 0}article span{font-size:12px;color:#a8bdc6}dialog{background:#111a21;border:1px solid #61737b;color:white;max-width:96vw;width:1100px;padding:16px;border-radius:9px}dialog::backdrop{background:#000c}dialog img{width:100%;display:block}dialog footer{display:flex;justify-content:space-between;align-items:center;gap:15px;margin-top:12px}button:hover{border-color:#e0bd7a}button:focus-visible{outline:3px solid #e0bd7a}
</style><header><small>FROSTMERE / REVIEW 02</small><h1>Forged, worn, carried.</h1><p>Named and faction equipment, ten armor families, eight ancestries and three body frames. Inspect studio silhouettes, face and helmet clearance, mixed outfits in stride, and every weapon in both gameplay cameras.</p><p>372 native captures · 837 checks passed · M5 Max / Metal. Select a category or search an item, then open any image. Arrow keys move through the filtered images; Escape closes the viewer.</p></header><nav><select id="group" aria-label="Review category"><option>All categories</option></select><input id="search" type="search" placeholder="Search item, ancestry or material" aria-label="Search captures"><button id="reset">Reset</button></nav><main><div id="count" aria-live="polite"></div><div id="grid"></div></main><dialog id="viewer"><img id="large" alt=""><footer><button id="prev" aria-label="Previous image">←</button><span id="caption"></span><button id="next" aria-label="Next image">→</button><button id="close">Close</button></footer></dialog><script>
const data=__DATA__;const $=id=>document.getElementById(id);let shown=[],active=0;
for(const group of [...new Set(data.map(x=>x.group))]){const o=document.createElement('option');o.textContent=group;$('group').append(o)}
function view(i){active=(i+shown.length)%shown.length;const e=shown[active];$('large').src=e.file;$('large').alt=e.title;$('caption').textContent=e.title+' · '+e.group;if(!$('viewer').open)$('viewer').showModal()}
function draw(){const q=$('search').value.toLowerCase(),g=$('group').value;shown=data.filter(e=>(g==='All categories'||e.group===g)&&(e.title+' '+e.id).toLowerCase().includes(q));$('count').textContent=shown.length+' captures';$('grid').replaceChildren();shown.forEach((e,i)=>{const a=document.createElement('article'),b=document.createElement('button'),img=document.createElement('img'),d=document.createElement('div'),label=document.createElement('span'),h=document.createElement('h2');img.src=e.file;img.alt=e.title;img.loading='lazy';b.setAttribute('aria-label','Enlarge '+e.title);b.onclick=()=>view(i);b.append(img);label.textContent=e.group;h.textContent=e.title;d.append(label,h);a.append(b,d);$('grid').append(a)})}
$('group').onchange=draw;$('search').oninput=draw;$('reset').onclick=()=>{$('group').selectedIndex=0;$('search').value='';draw()};$('close').onclick=()=>$('viewer').close();$('prev').onclick=()=>view(active-1);$('next').onclick=()=>view(active+1);document.onkeydown=e=>{if(!$('viewer').open)return;if(e.key==='ArrowRight')view(active+1);if(e.key==='ArrowLeft')view(active-1)};draw();</script></html>'''
(root/'index.html').write_text(page.replace('__DATA__',json.dumps(entries).replace('</','<\\/')))
validation={'checks':837,'failures':0,'suites':{'equipment_fit':480,'characters':36,'combat':46,'crafting':201,'loadouts':17,'mage_projectiles':57},'studio_captures':238,'gameplay_captures':134,'hardware':'Apple M5 Max; native Metal Mobile','status':'Implemented; awaiting user visual review','limitations':['No M1 validation or new performance benchmark','Fit checks and sampled poses do not prove every possible animated outfit is intersection-free']}
(root/'validation.json').write_text(json.dumps(validation,indent=2)+'\n')
print(f'Gallery ready: {len(entries)} verified image paths')
